import hashlib, json, pathlib
from html.parser import HTMLParser
from urllib.parse import urlsplit

source = pathlib.Path('products/services/peppol-implementer-pilot/raw/openpeppol-provider-navigation.html')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '41db92d2709636a03d99d6b5c5143b76e668557992a16565ecee803b8c3fa015'

class Navigation(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.href = None
        self.label = []
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.href = dict(attrs).get('href')
            self.label = []

    def handle_data(self, data):
        if self.href is not None:
            self.label.append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.href is not None:
            self.links.append((self.href, ' '.join(''.join(self.label).split())))
            self.href = None

page = Navigation()
page.feed(raw.decode('utf-8'))
hosts = {}
for href, label in page.links:
    try:
        url = urlsplit(href)
        host = url.hostname
    except ValueError:
        continue
    if url.scheme != 'https' or not host or url.username or not host.endswith('.ca'):
        continue
    host = host.removeprefix('www.')
    hosts.setdefault(host, label if label and len(label) <= 100 and '@' not in label else '')

result = {'source': 'https://peppol.org/members/peppol-certified-service-providers/', 'source_sha256': digest, 'anchors_parsed': len(page.links), 'distinct_ca_host_count': len(hosts), 'shortlist': [{'host': host, 'directory_label': label} for host, label in list(hosts.items())[:6]], 'interpretation': 'Navigation only. The .ca suffix is a bounded filter and does not establish provider certification, country of operation, supplier intake, paid demand, or eligibility. Non-.ca providers were outside this extraction.'}
output = pathlib.Path('products/services/peppol-implementer-pilot/director-ca-navigation.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
